BEGIN;

SET LOCAL search_path = public;

ALTER TABLE public.professor_review ENABLE ROW LEVEL SECURITY;

ALTER TABLE public.professor_review_course ENABLE ROW LEVEL SECURITY;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (152::BIGINT, 'Es una excelente profesora y un amor de personan se esmera en que el estudiante aprenda sin embargo la profe deja muchos trabajos para ser un curso de un crédito pero en general se aprende mucho y se pasa mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2026-02-18T00:00:00+00:00'::TIMESTAMPTZ, 'f4e082e5a013188ee7630025650626c5c875679d07bdb6324ef888e70de3482c'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Un amor de persona y de profe, uno aprende demasiado y la profe sin duda tiene vocación para enseñar, matricule con ella'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-14T00:00:00+00:00'::TIMESTAMPTZ, '93680ca50a9575852db25fd172b9de1ebc565c9c05893bfbc24d6306e593bef8'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Llevé ambos cursos con ella, es la mejor profe que me he topado en el Tec. Si ud falla alguna tarea, lo pone a volver a hacerla para darle un 100. Es facil pasar y ella es un amor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-17T00:00:00+00:00'::TIMESTAMPTZ, '70746cfed5857bcda900260d61d8ff21f6670353ffe591eda79322b6d3fb868a'::TEXT, ARRAY[600, 554]::BIGINT[]),
    (152::BIGINT, 'La mejor profe, sin duda alguna! Hace que en la clase no sólo se aprenda, si no, que sea un ambiente agradable en todo momento, no es difícil aprobar el curso con ella. Sin pensarlo dos veces, lleven el curso con ella.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-07-01T00:00:00+00:00'::TIMESTAMPTZ, '4cb9b89befab9297a975af4522a83b1a05a798b267dabe642fec2705bca4e6bf'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Se hacen distintas actividades (discursos, presentaciones, ventas de productos, modalidades grupales orales). Se aprende demasiado todos esos tecnicismos de expresión oral. La profe es excelente y se pasa super fácil, eso si, preparese para hablar!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-16T00:00:00+00:00'::TIMESTAMPTZ, '6df11cd7ed37238cf78a9f5ec702307c51ec3e4c6f703e7f58b602b040296b63'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Muy buena profe, matricule con ella sin dudarlo. Lo único fuerte del curso es un esayo que deja a mitad de semetre, pero da mucho tiempo para hacerlo e incluso ella le da el formato. Todo lo demás excelente, las clases son relajadas y muchas las deja virtuales.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'c09defe2d0b392ced5d670d98bcc39cf37c94dca61cb473b2c1fbdd62e571c38'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Una profe super amable, siempre dice cómo quiere que le hagan los trabajos (qué poner y qué no) tarda un poco en responder el telegram, fuera de eso la recomiendo 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-29T00:00:00+00:00'::TIMESTAMPTZ, '4064d0d79617f6e4cfa7491c00b202c33a8b4888cd7939035820d9b8fa40030c'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Una profe excelente, la recomiendo una y mil veces. Es demasiado dulce y te ayuda en lo que necesites, da oportunidades para que corrijas y aprendas de tus errores. Las tareas muy sencillas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, '7899b25e6d9bf26f9163e05b661ed38a25f90492991d2f01e0e785a88067db5d'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Muy buena profesora, no califica duro y es comprensible con los estudiantes. Tanto comí escrita como comu oral con ella son un buen paquete para así aprender mucho más. Da buena retroalimentación entre otras cosas, el único problema es que suele tardar en responder un poco el Telegram.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'bd1e922d2a63b277bdc92385ef12eb2f03285810e2c000e374b7b649bb06d71d'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Es muy buena gente y sus clases son bastante entretenidas. Es muy ordenada, sus instrucciones son claras y da mucha retroalimentación. El curso se pasa fácil si usted entrega todo a tiempo y hace las correcciones que ella le da.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-11-23T00:00:00+00:00'::TIMESTAMPTZ, '01a7774cf472abc1a7ea8ff56443b524195f81783e2d9951818e2307d1ca5253'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'La profe es un amor de persona y una excelente profesora. Da tanta retroalimentación que al momento de hacer las exposiciones ya sabes cómo hacerlo y sacarse 100. Evalúa bien y además que si no tienes 100 te deja entregar las cosas hasta que lo tengas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-06T00:00:00+00:00'::TIMESTAMPTZ, '8879dc36ecdce9c61f9ef35dc97755bf1f0c3ac02aa53ce6a30f4ab71aca3e89'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'La profe es amable y simpática. Se aprende mucho en sus clases y hace el curso fácil e interesante. Hace varias evaluaciones, sin embargo, califica suave. Reconoce el esfuerzo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-07-25T00:00:00+00:00'::TIMESTAMPTZ, 'c603bf30b6065522ede6ec7351224a96aa180023e17be9b02b3d6bc3f8948c42'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'La profe cae muy bien, la clase fue un ambiente positivo. Prepara documentos muy claros del trabajo en y fuera de clase. Le gusta mucho dar comentarios de los trabajos pero no suele rebajar de la nota. La clase no es matada, quizá lo más difícil fue a la mitad con el ensayo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '1a0f024523650911cf2a2217e8216bb60c88b00897ed28c2d68234c3249a18b7'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Excelente profesora, la recomiendo, el curso es relativamente sencillo puesto que explica muy bien y se nota la pasipon a la hora de enseñar. Es comprensible con los estudiantes y muy buena nota. La clase es muy dinámica y entretenida, diría que tiene un balance casi perfecto.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, '03f633054fb9d0cc4ba1181a1fd08029f68e118657dd9db55aa13ed5b95f0ded'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'No me pareció una profesora tan buena como muchos mencionan. Se nota la preferencia por algunos estudiantes. SE TOMA LAS COSAS PERSONALES Y NO ESCUCHA OPINIONES DIFERENTES A LA DE ELLA. No volvería a llevar ningún curso con ella.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-05-30T00:00:00+00:00'::TIMESTAMPTZ, '7acc497a6568c2ad52f15380b1207e21c70912a3cc98729fbb0f799d4e75cde1'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'La mejor profe, califica bien y explica muy bien sus clases'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-05-17T00:00:00+00:00'::TIMESTAMPTZ, 'be7afeab7f9494aaf5920c93e6b7175aaa090abc1c202671f6c2dbed8904dba8'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'La mejor profesora que he tenido a nivel de comunicación. Se aprende muchísimo de ella, es atenta, se preocupa porque los estudiantes aprendan. En general es excelente, recomendada 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-14T00:00:00+00:00'::TIMESTAMPTZ, '7d0b93d2b1d787562381f147385c1a7279d63c988119a4e9a379d643e78a9cf0'::TEXT, ARRAY[601]::BIGINT[]),
    (152::BIGINT, 'No dude en matricular con ella. Es súper amable y educada. Las clases son amenas y hace que uno tenga interés en la clase. Los trabajos no son nada del otro mundo y siempre las instrucciones son muy claras.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'bbf65e2f1d8e82a1254e9a5518be6ee08d521098596d792b7a18f1cce172a595'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Da buenos consejos y retroalimentación a cada estudiante. Excelente profe, amable, graciosa y califica bastante bien. Muy recomendado, aprendí bastante.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Inspirador']::TEXT[], '2023-12-07T00:00:00+00:00'::TIMESTAMPTZ, '9437803881eefd844837b323c2a9f85df6b1516b63932ec6c56816a299415444'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Tqm a la profe, se interesa muchísimo porque uno de verdad aprenda y mejore en presentaciones orales, me ayudó mucho. Sí deja bastantes trabajos durante el semestre (y expos obvio) pero no consideraría el curso pesado ni difícil, la profe no es nada estricta y es súper flexible y buena gente.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-24T00:00:00+00:00'::TIMESTAMPTZ, '640273bf65ab75710b491e82b5bca0db602f2c6edaf783dc9a1ba9b959c45824'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'La profe califica un poco duro, pero es muy buena persona y las clases se vuelven muy amenas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2023-06-27T00:00:00+00:00'::TIMESTAMPTZ, '2ce52aa5d654ff68d57c2a201cc7dc06f7c779ac2e167b3867ebd09bf26c1f27'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Califica duro pero justo. Bastante entretenido. Y los proyectos eran claros.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'cc90545b8a0cb81f8c4d0a82a3e7cfd6181d95b036c375106f2a565b75761186'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'La profe le interesa que usted aprenda, es por esto que deja subir correcciones de los proyectos para que mejore la nota. Da muchos tips de escritura y quiere que usted disfrute de la materia, tanto es así que permite escoger el libro que usted guste para leer. Definitivamente recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '62798217f516532dda6c5c0dec96edc81d6a8f503da723f746f9d2ecb21eb5b4'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'La prfe es excelente, explica muy bien y es super amable. Los trabajos da chance para subirlos de nuevo corregidos. Lo único feo es si no te gusta leer, hay que hacer varuos foros sobre la lectura de un libro.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '19ceb6e61b3f99fc964643f94b1ad0edeeb02111b47e1b2279cf944f1e9fbf49'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Se aprende bastante con la profe y se pasa fácil con que sea responsable y siga instrucciones. Atiende las dudas y da muchos consejos para redactar. Súper recomendada.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '37bb7238c2aecb6cf21420679b467d9f16fc0acb735a8fce3dee47b14496bf80'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Se nota que le apaciona mucho lo que enseña y está dispuesta a ayudar a los estudiantes en todo momento. La materia es fácil y si uno se esfuerza, puede sacar buena nota.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '057fdc6f2758448e854b543f5e96c56d613e97175f9fdfbfdb5d2a44c1aad386'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'La profe es muy buena gente y busca que todos entiendan. Es importante escribir bien en los trabajos. Además, le interesa que todos tengan buenas notas, por lo que busca dar tiempo de correcciones'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '856e716caac7d5f423cf4a5737a171c0a8917f251bbf5174acf08c5c144b81db'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'adopteme profesora'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '7e3ca6330a983752b0e682cb47f909330ede5819a20264731a199921c72e9bd1'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'está genuinamente interesada en que uno aprenda todo lo necesario, tiene demasiada vocación, no dude en matricular con ella'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'a61ee45a074773c04a358365e1889e427f770d2b47649b7e3d84ad9885902968'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Excelente profesora, super bella gente, explica demasiado bien, se aprende montones y las clases no son complejas. Da toda la ayuda que necesite, recomendadísima.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-12T00:00:00+00:00'::TIMESTAMPTZ, '3d5fddbc7381d16e6a7461cdc0328d9493188496a62ba8689b1967add7af6987'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Es un amor de persona. El curso es muy relajado, pero al mismo tiempo se aprende bastante. No dude en matricular con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2022-12-08T00:00:00+00:00'::TIMESTAMPTZ, '6a6ffbb7dc9626da2fb2c1c102ffa82f72fd0849fdc5f2992ede6c5377d5c162'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2022-12-06T00:00:00+00:00'::TIMESTAMPTZ, '77c5a7044b24ab2529d8d8e20030dd141357fa840526f5b299280ce95fdf4246'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Excelente profe de comunicación, brinda mucho apoyo y no es estricta. Las clases las hace muy activas, y es una buena persona en general, en el trabajo final nos dejó exponer de lo que quisiéramos, ya con eso es suficiente evidencia de que a ella sí le importa el bienestar de sus estudiantes,'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2022-11-08T00:00:00+00:00'::TIMESTAMPTZ, '0632fc91c2f8272f9ebeee27448c4270ad9ffaeee32014e1db15546d8b2b4803'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'La profe es poco empática, no tiene desarrolladas las habilidades blandas, rígida con sus pensamientos, no tiene capacidad para razonar o dialogar para resolver problemas de la clase, humilla a sus estudiantes y hace comentarios hirientes en frente del resto de la clase.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-02T00:00:00+00:00'::TIMESTAMPTZ, 'cc81d070b64c6b4f8a3a0e727ec03eb8254ef66b58d303132a40cf62a7d5cc8a'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2022-09-15T00:00:00+00:00'::TIMESTAMPTZ, '5cd6ca38c8ba25ff1462005d52f528b5ecfd92645b7c8dd51c1d7dbffe6e2bb7'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Muy buena profe. Todo estaba super organizado, y nota el esfuerzo que uno le da al curso. Califica con rúbrica, y da retroalimentación.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-07-02T00:00:00+00:00'::TIMESTAMPTZ, '9fbcf26700949afa9781f1fc45d67f5799268c3ec9f972e82075eb47b2e779e3'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Excelente profe! Pendiente del estudiante y otorga mucha retroalimentación, le gusta la excelencia en los trabajos, pero es muy justa calificando si nota su esfuerzo, hace el curso super interesante. Se aprecia su vocación y dedicación, no dude en matricular con ella, es un amor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-30T00:00:00+00:00'::TIMESTAMPTZ, '7612c0a48699836379e5aaf77616861d89afb79c8126ca538c1d3aa07d4b7c5f'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Buena profe, da buen tiempo para los trabajos y explica bien. Yo llevaría de nuevo con ella, super buena gente y todo. Si es importante asistir, pasa lista.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, '5c0e56b3058315faea1e5035908e6f8597f97a14746b1d49aa600e0467d0aff8'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'ec5733624743e55d55c8cc016982d880e36420d80c06f0ebf87aeb9f4daf8e8b'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Es una excelente profesora, brinda bastante apoyo y buena retroalimentación. Manda muchas tareas pero casi siempre le pone el 100 si las hace a cabalidad, en los exámenes es demasiado exigente y califica duro.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2022-01-30T00:00:00+00:00'::TIMESTAMPTZ, '25cf6dace8fef3b79720404ee0fb4fb47a266ded87e30275317915da1108846d'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Muy buena profe. Con entregar las tareas y trabajos, le pone 100, pero para los proyectos y exámenes sí le califica la nota. Lo bueno es que da mucha retroalimentación y le ayuda a mejorar las posibles fuentes de error. Las evaluaciones terminan temprano en el semestre (~semana 14).'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'a585784117d716ba82fbd39b9e8d6825a7a42588719ac42a04d71432fac050f5'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Es una buena profe. Los trabajos son en grupo pero ella califica individualmente. Es muy consciente del proceso de aprendizaje, por lo que lo que más le importa es que uno ponga atención y se esfuerce (Revisa gran parte de los trabajos antes de la entrega oficial y uno puede hacer correcciones).'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, '317357ee35e9784218c9312d96f110894809bfb83c99ae839aab378321060a4a'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'De las mejores profes del TEC, aprendí mucho con ella y sus clases eran entretenidas. Aun virtual fue un curso que se aprendió montones.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, '3d10c801fad8c1957af35f573ac055b90c88afac3f8d4e7213f12620c9de7504'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'De manera virtual es una excelente profe, da las clases muy claras y ordenadas. Deja muchos trabajos y uno tiene que ser muy responsable, pero estos trabajos no son nada difíciles. Califica relativamente duro.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '9cc0e7a5607b09c012cfe692b0f9c5f14225551eaa309f2fca1aa60e994f5199'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Ella es genial. Como persona es super amable. Como profesora, explica bien, los trabajos son fáciles, las clases se entienden bastante y se puede pasar con buena nota. Super recomendada.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '55c7d10e2593ac40175fecaabeccdadf3ca4d5ee5644b207f58bd7d0fb3357cf'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Es una muy buena profesora, es agradable y se esfuerza porque uno aprenda. Llevé su curso en modalidad virtual y fue excelente, imagino que en presencial sería aun mejor. No es difícil, pero sí hay que esforzarse por realizar un buen trabajo y entregar todas las tareas, aunque sea atrasadas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2020-12-05T00:00:00+00:00'::TIMESTAMPTZ, '56c29640f0734c07c27d5b0bd614ce5c4537b747c004c9de74fa89792e73b6a1'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'La lleve en modalidad virtual, ella prefería las clases asincrónicas, y los correos los respondía muchas veces un día después, si no se encontraba en el horario de la clase'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, 'c6d2547f23666dc6e5a5c42f9fba799df3ac6a76437ea11843e6049c87fdfb8e'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Ella es un amor de persona. Y como profe también es súper genial. La materia no me gustaba para nada y ella la hizo mucho más llevadera. Además, ayuda muchísimo al estudiante e incluso da muchas oportunidades. Simplemente genial.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '1445a10e773f7cfebb63b8ac13846625fd3389abd0c74103d09e63a2f9a8a8bf'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Buena profesora es bastante atenta y da muy buena retroalimentacion, pero es bastante detallista al calificar y sus rubros no siempre son muy precisos.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '0a903a2b18d6b562c72241725520d8cbbc6a169eb2216061f788a1b8eeac6471'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Las clases tanto virtuales como presenciales son excelentes, va directo al punto y siempre se le entiende. Responde dudas rápido por correo. En la clase se aprende bastante y el curso no requiere mucho esfuerzo, aunque sí es detallista a la hora de calificar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'ca26c51802b08d37f971638b1da2dcb6269742adc54bea0ceff9319b68d6f574'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Muy buena profesora en clases virtuales o presenciales, todo lo explica muy claro.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'ea964e434aaea634c54636a2e7bbbd2bbc66dd6642b5fb07096f358a67a9616a'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Excelente profe, da el curso super fácil y se aprende mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-31T00:00:00+00:00'::TIMESTAMPTZ, '3f791e79fe5207746ce44a704a436465bf0c998f13ce6759c9adda519f51dc32'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'd47124132e728db8f3cafd3f45eb13a23f971152f06a28bbfdee14a2f1519048'::TEXT, ARRAY[555, 601, 266, 264]::BIGINT[]),
    (152::BIGINT, 'Una profe que de verdad busca que el estudiante crezca.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, '3e35f4e19b908e23570d9bd3dc41bb3fe73201bcaa19adadd73416051c2818f0'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, '100% Recomendada, es super fácil el curso con ella se pasa.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Respetado por los estudiantes']::TEXT[], '2019-12-16T00:00:00+00:00'::TIMESTAMPTZ, '0e6b68f8028b1fa39ce017d8d932d4ce26f47f605becf7411a6c338d7b95dc33'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Demasiado buena, se pasa super fácil y se aprende un montón. Solo que si no le gusta la irresponsabilidad pero siempre pasa hasta terceras oportunidades para entregar las tareas. RECOMENDADA AL 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'c8bff2c92f9e5392e6d539097296e398a8a3448ffbf010086febd91e6b292911'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'La profe es muy buena, se aprende mucho y no califica duro solo que si deja muchas tareas para ser un curso de 1 crédito y hay que ser muy responsable. Si hace eso puede tener hasta un 100 de nota, sino la nota puede bajarle por que no le gusta la responsabilidad.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'La participación importa']::TEXT[], '2019-07-29T00:00:00+00:00'::TIMESTAMPTZ, 'd45c888dda14ea5dc7fce4bf87eb5c3c688304f90b74b4b675e3165e35c7320d'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'La profe deja muchos trabajos durante el curso, la mayoría son fáciles, pero uno siempre tiene algún trabajo de ella en todo momento. Califica suave pero el ensayo escrito tiene que quedar muy bien hecho ya que ella se enfoca en eso. A veces se pone en mucha vara, pero es buena nota y muy ordenada.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '2f78eb93490b2dbb8708fea3a624f15528984d9310861c25b01282a68b148fa7'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Es una excelente profesora, muy organizada con el tiempo de una manera que la entrega de tareas no choca con otras asignaturas, además para ella lo importante es que el estudiante aprenda, por eso da la oportunidad de corregir las tareas y te da muy buenas calificaciones si trabajas bien y ordenado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'ef49a3ca279d4bcc0b8a9376460e7a3bfaacc0c60ff5688ef5a4c2cc997fcb95'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Una profesora muy pero muy buena y además es muy linda con los estudiantes. Disfruté cada clase y aprendí un montón. Organiza muy bien el tiempo. Los trabajos son larguillos pero nada del otro mundo. Eso sí, deja MUCHAS tareas, pero estas son de gran utilidad. No duden en meter clases con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2019-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'a7a34ef4563a311caf31192aa1fe5970df3f94d294215e3b38f94a1a0ea14777'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Muy buena profe. Da oportunidad de corregir los trabajos y ayuda bastante para mejorar muchos aspectos de escritura y redacción. Se interesa por el aprendizaje de sus estudiantes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2019-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'b8cee5ec4bab02dae9edcb08ab0ee4f9385728c822a02cf6b18cfb3d63fa2af1'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'LA MEJOOOR'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-31T00:00:00+00:00'::TIMESTAMPTZ, '2a069c84b3f79120ecbe5f49a1db23a2a319b214febabef83c22a6baf43232d2'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'La profe es muy buena gente y su clase es súper fácil. Deja muchísimas tareas que aunque son fáciles, toman tiempo; lo bueno es que a todos les pone 100 sólo por hacerlas, pero claramente deben estar bien hechas! Es una clase regalada siempre que usted sea responsable.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, '978fd8d3fa7b35f34577edabc7b2a30f16e2e3d5c90e46b5dab25c4c99edc474'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'La clase es amena, la profe es muy buena gente y explica bien. Deja bastantes tares, fáciles pero muchas. Si quiere vaguear no matricule con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Inspirador']::TEXT[], '2018-08-18T00:00:00+00:00'::TIMESTAMPTZ, '97a8906a6698a82ad6058cf526464dac7e417bc3763e3e74316de3e62b065cbd'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'aaa4d117715afda0708e8e64b46477db7fdede86902e45456262c5c8d08bb845'::TEXT, ARRAY[601]::BIGINT[]),
    (152::BIGINT, 'Es una excelente profesora. Deja bastantes trabajos relativamente largos, pero fáciles. Es muy simpática y comprensiva. Su prioridad es que los estudiantes de verdad aprendan y eso es bueno. Va a exigir un compromiso con la materia. Es organizada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'f4e99a18d605b68b23948e672606d81c83ad9df60a58e916589dc51940cfdae3'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '43aac3973a3de5975aaf703f5dc74b3cf3a07dfef4a0556d18332c6460208863'::TEXT, ARRAY[600, 554]::BIGINT[]),
    (152::BIGINT, 'Excelente profesora. Explica muy bien la materia y repite todas las veces que sea necesario para que uno sepa lo que tiene que hacer. Suele atrasarse con las calificaciones, pero es comprensible. Se hicieron dos trabajos principales, cada semana había que hacer una parte, hasta finalmente terminarlo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'ee5b9f7bec06836eb353ed0b8de2f2a28a42c267401d6deab1afc226584fe634'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Muchas tareas, pero explica bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2018-05-20T00:00:00+00:00'::TIMESTAMPTZ, '9dbc96b319c5c3e1d71b2ded0570322ebb6eed5339b88cd88263e3fe30afd384'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Excelente profe, las clases son muy entretenidas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-04-08T00:00:00+00:00'::TIMESTAMPTZ, '9878c6a3d35fd38916dcccf158e98c35c337eecdad757de718a1f4c4247a5393'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'DEJA DEMASIADAS TAREAS, para que el curso sea de 1 crédito. Es muy buena nota y sumamente divertida. Pd las tareas son muy fáciles'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2018-01-02T00:00:00+00:00'::TIMESTAMPTZ, '6c4bfa153694d1f125d9114a0390f7fa28c268375eb019a9734333763d5bfae8'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-29T00:00:00+00:00'::TIMESTAMPTZ, '468273692b5579ef6f03d21d48f89dc1165be50293e34636d9a6219f92719c6c'::TEXT, ARRAY[554, 600]::BIGINT[]),
    (152::BIGINT, 'Deja muchas tareas, pero son fáciles, la profe es super buena nota y ayuda bastante. En la exposición final es un poco estricta'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'fc7fbf49a6da5344a7b5eb50c29b7671f7112007c5574acd09dc07c95094a264'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Deja muchas tareas pero no es estricta al evaluarlas. Explica bien y es divertida'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2017-12-08T00:00:00+00:00'::TIMESTAMPTZ, '45595fbbbf26bdd07888a00f29ab3b66f2138448da4736f1cd70b29c18427092'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-07T00:00:00+00:00'::TIMESTAMPTZ, '2719e9947cadc1d8f201ccd77ec833376fd6c88d8e94d40766d6ed153f56167d'::TEXT, ARRAY[554, 600]::BIGINT[]),
    (152::BIGINT, 'Excelente profesora, un mil de persona y se preocupa por sus estudiantes. Hay tareas casi todas las semanas pero nada que quite mucho tiempo. Totalmente recomendada'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '2621463b3297a615dd748b15759d227b47cd698af8ece7d9ec2dec7554d6b476'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-08-09T00:00:00+00:00'::TIMESTAMPTZ, '44f5402703851c4b6f6d9bc50c59e1d99bd726d23185c2f5c88314458e5ae802'::TEXT, ARRAY[555, 601, 266, 264]::BIGINT[]),
    (152::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'd69f67b4b8ec78dceb7c0e24be422426c92dde6099ab689bf315d01608266dc2'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'La personalidad es súper linda y se preocupa porque uno haga las cosas bien. Súper recomendada.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'ed086b299e330fb3028a4c3229de348f1c7ca857cb45d4439dcc1569c14593d9'::TEXT, ARRAY[554]::BIGINT[]),
