    (152::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '764fac9eb51c73010eec26e420d85fa8d01499cd08c7a97d7744472f622f4d04'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Demasiado desordenada'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '7dd009c29c56ae22cf7af6fd2aecb491b3e7b45e763feda9ff30e8e49b1461a2'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Es muy buena, deja muchos trabajos, pero siempre da la oportunidad de corregirlos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, '2df12f3c7a6aaa2735c7acaa08ebe76800dbbcd39d6231bfa2d4568d9b0c32b2'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, '8a8628701ef6e1e2c12e43d04c76b9a47e0ed4b7aff1363174c96dd4a0c10ac8'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Ella es muy linda persona, pero los trabajos son pesadillos, sobre todo si el semestre es pesado. Da la oportunidad de corregir.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, '9f8734d1316c0ae491dffa905fdd729311d4e3b979fc4b0f7f5564fd01289dd2'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, '9738173e29e3e5f81761aaeec79daa83ce4176cb96912612c02228c1427581f1'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Deja bastentes trabajos, pero nada imposible . Aparte de eso muy buena profesora'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases largas']::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'e67b12bf74b2ca118ec591360fd5973c5d4309b537656fa3cba54345b3562cbf'::TEXT, ARRAY[554, 600]::BIGINT[]),
    (152::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2017-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'dc387c282f4fba0e38686f9dfe412b436e32f96c2e1ce222a6016cd12bc6b767'::TEXT, ARRAY[601]::BIGINT[]),
    (152::BIGINT, 'Exc!! La mejor profe que hay!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2017-01-17T00:00:00+00:00'::TIMESTAMPTZ, '14010607f407ffc73ec082f8039dd6613bbbfca6656c5dad7fdd74c2fb3502e0'::TEXT, ARRAY[123]::BIGINT[]),
    (152::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-13T00:00:00+00:00'::TIMESTAMPTZ, 'e0df0ef2726527cca34e6a4de7a3072e6de277a66eda6ee4144e1449fd21d49e'::TEXT, ARRAY[555, 601]::BIGINT[]),
    (152::BIGINT, 'Súper recomendada, lo importante es poner atención por si te pregunta algo. Si fallas un trabajo te da la oportunidad de correguirlo. Yo pasé el curso con 100'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'cb162597fa655e1cdc2a40f8e6142a691a57d0041a0a3edf0cbeb8c93f07f970'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Es un amor de persona, de la mejores profes que hay. Deja bastantes tareas pero son muy fáciles y valen bastante entonces ayuda a la nota, solo hay que ser responsable y ya. Distribuye muy bien los contenidos del curso, se avanza de poco en poco y se pueden corregir los trabajos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2016-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'eca5c1590b69e6f0cd608338ddd0dccc0af5461ef39339209f97530fdafb7679'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'No revisa los trabajo de manera clara, además si la agarra en contra tuya pariste el semestre.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-17T00:00:00+00:00'::TIMESTAMPTZ, '71477171a83a9dff1de60881858e2501a2e9ff740e9177909ac6de70560f5801'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Es super facil con Maria Gabriela, lleven todo lo que puedan con ella'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Muchos proyectos grupales']::TEXT[], '2016-06-15T00:00:00+00:00'::TIMESTAMPTZ, '71988c6a9a87fb3b068669a503fa4aa9b4be075272e64c317ad9001f5b7cef30'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Deja trabajos pero son super faciles y si uno los arregla le puede dar el 100'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'cfb2b1c629edada3c8bbdc178f086ca2ce925261639729b78ef5d655d249c074'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Es muy buena profesora, hay que ponerle eso si. Participar en su clase, mandarle un correo en caso de duda, ella toma todo eso en cuenta. Deja muchas tareas pero no son taaaan largas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '9cb014d79b5431fa1cb985d0784dc9aaf7db09f4392486cd3969660611064c68'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'ca5d9e3e6ed621f710107e0728fd63f2370d47aef78284b8faf9a7db39429410'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-04T00:00:00+00:00'::TIMESTAMPTZ, '315b6614495a9f019c1a4f24782deea62a5b1e19e7ad356edfbf97adbc2b2770'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Hace su clase amena, es muy buena en lo que hace y sabe demasiado. Trata de que todos entiendan. Además es muy linda físicamente y como persona.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2016-05-10T00:00:00+00:00'::TIMESTAMPTZ, '685af76616592634ffa921464938b0c893354ebfc143df26149d5725662c869c'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Excelente profesora, ella me enseñó lo que es la comunicación. Ahora hablo en público, redacto documentos... Increíble la pedagogía'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-16T00:00:00+00:00'::TIMESTAMPTZ, '52a5634a428f33458a71dabc3f8a7b8ee488b4602b5912f418279593134b2846'::TEXT, ARRAY[554, 600]::BIGINT[]),
    (152::BIGINT, 'Después de las primeras lecciones no vas a querer que se acabe el curso, uno aprende montones y, si el grupo habla mucho, también será divertido. ¿Ella es genial! Sabe un montón y siempre quiere el bien del estudiante. El único detalle: PIDE DEMASIADOS TRABAJOS.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-11T00:00:00+00:00'::TIMESTAMPTZ, 'f6d693018da76606ed4bce934a5418a5d31e0609d97e81d0d722a051db8e4801'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Muy linda persona'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-23T00:00:00+00:00'::TIMESTAMPTZ, '9b677e68b3e8f93aef8ac77e058254b0230cab02d9cc78902b954e4c366da5bc'::TEXT, ARRAY[554]::BIGINT[]),
