    (152::BIGINT, 'Super buena profe, ayuda montones con consultas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '5b8e652efe5d050ec79c60e426f302c176d297a3fe2222c6e373c50b8c1cb0cd'::TEXT, ARRAY[554]::BIGINT[]),
