    (152::BIGINT, 'Después de Carolina Gómez, la mejor profe de la Escuela :)'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'ece3d15150066723dab32264bace302f3454c64e66cd4778df826926e6cfa902'::TEXT, ARRAY[554]::BIGINT[]),
