    (152::BIGINT, 'Como profe, como profesional y como persona es excelente.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'ceb69c2a0e6a2f37b144a52f123e4f28a0809fa3b799fa78fb88c2530c23c99f'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Excelente profesora'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '2ddf4c260682ac0269d3524f6f28fe1709f73f92a3e6a1a470c517d1919345f1'::TEXT, ARRAY[600, 554]::BIGINT[]),
    (152::BIGINT, 'La profe Gabriela es muy buena, sabe mucho y se nota su pasión por lo que enseña, por el TEC y por esta etapa en la vida. Lleven con ella, se hacen varias cosas eso sí, pero la clase es un buen cambio de lo demás que hacemos. Pasa motivándolo a uno y siempre está del lado del estudiante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Inspirador']::TEXT[], '2026-01-20T00:00:00+00:00'::TIMESTAMPTZ, '9282f7c21236b7745b0ec0dd870019d9be9cd8664dbcbb428f75667ac354f675'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Sus clases son entretenidas, se interesa en que usted aprenda los contenidos del curso y más para que se prepare en general, excelente profesora que califica justo y da mucho tiempo para las evaluaciones y los examenes son relativamente faciles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'b70a03e77ca52f2bfd47e29ae1b0449005cbcb49308c952e50252e096214f922'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Si tiene la oportunidad no dude en matricular con ella, es muy linda persona, realmente se interesa por que usted aprenda, las clases son dinámicas, el curso se pasa facil con 100 si usted es responsable, califica justo, la recomiendo totalmente!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2025-11-20T00:00:00+00:00'::TIMESTAMPTZ, '27922d3bb89dda86190bdc1afdb3676b94bcb51652c601f3b5f46fb2c82398b5'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Cae súper bien, ayuda a mejorar las habilidades de uno. La clase no es difícil sin razón, pero a veces tienen que coordinarse bien en grupo. Recomendada 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2025-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'bfc5004ae21daf39671881046f1e354291e3483bed52cc1311d7f093111ec2d8'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'La mejor profe, se aprende un monton en su clase y se disfruta bastante, si son responsables fijo pasan con 100'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Brinda apoyo']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '93a8137a04f9b1652196d14efa8403bccc31c1b4ddf1089d78fb01acfd7dbe4a'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Lo mejor que puede tener la Escuela de Ciencias de Lenguaje. Es súper amable, comprensible, atenta a sus estudiantes y siempre busca la mejor forma de enseñar. Definitivamente no dude en matricular con ella, porque explica tan bien y tan claro, que aparte de aprender, también se disfruta.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'cd2c91f69dc8e5d7e9f43ee58ddc50300307248a423e05d8b1ec84500b601601'::TEXT, ARRAY[600, 554]::BIGINT[]),
    (152::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2022-06-25T00:00:00+00:00'::TIMESTAMPTZ, '880e1885900d1838ff3394af8850999c9d7254e1ed2a033ca73b0f1740ef7566'::TEXT, ARRAY[554]::BIGINT[]),
    (152::BIGINT, 'Ella es genial. Como persona es super amable. Como profesora, explica bien, los trabajos son fáciles, las clases se entienden bastante y se puede pasar con buena nota. Super recomendada'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '7b725c468e079a5c2e3792fd93a004c55cdb58df4ff3516f0bec45cfdf38e652'::TEXT, ARRAY[600]::BIGINT[]),
    (152::BIGINT, 'Excelente'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Inspirador']::TEXT[], '2020-07-29T00:00:00+00:00'::TIMESTAMPTZ, '62c723550240d7a6249456be7848dfa00bdd128f371ad37aeb95f18bdd5672cb'::TEXT, ARRAY[554]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
